INSERT INTO avaliacoes (id, quadra_id, usuario_id, autor_nome, nota, aspectos, texto, util, resposta, resposta_em, created_at) VALUES
    (1, 3, NULL, 'Mariana Costa', 5, '["Iluminação","Atendimento"]', 'Ótima quadra, bem cuidada e com iluminação excelente. O atendimento também foi muito bom! Já marcamos o próximo jogo.', 12, 'Obrigado, Mariana! Ficamos muito felizes que a galera curtiu. Esperamos vocês no próximo jogo!', NOW() + INTERVAL -2 DAY, NOW() + INTERVAL -3 DAY),
    (2, 3, NULL, 'Lucas Ferreira', 5, '["Estrutura","Localização"]', 'Espaço organizado, grama em boas condições e fácil de chegar. Recomendo!', 8, NULL, NULL, NOW() + INTERVAL -9 DAY),
    (3, 3, NULL, 'Rafael Martins', 4, '["Limpeza"]', 'A quadra é muito boa e os vestiários estavam limpos. O estacionamento poderia ser maior em dia de jogo.', 5, 'Valeu pelo retorno, Rafael! Estamos ampliando o estacionamento e a obra termina no mês que vem.', NOW() + INTERVAL -14 DAY, NOW() + INTERVAL -16 DAY),
    (4, 3, NULL, 'Camila Souza', 4, '["Custo-benefício"]', 'Boa estrutura e ótimo custo-benefício para jogar com os amigos.', 3, NULL, NULL, NOW() + INTERVAL -24 DAY),
    (5, 3, NULL, 'Bruno Almeida', 3, '[]', 'Quadra boa, mas a reserva atrasou 10 minutos porque o jogo anterior não liberou no horário.', 1, 'Bruno, pedimos desculpas pelo atraso. Agora deixamos 10 minutos de intervalo entre os jogos para isso não se repetir.', NOW() + INTERVAL -38 DAY, NOW() + INTERVAL -40 DAY),
    (6, 3, NULL, 'Fernanda Lima', 5, '["Iluminação","Estrutura"]', 'Melhor society da região. Iluminação perfeita para jogar à noite.', 6, 'Valeu, Fernanda! A iluminação nova foi pensada justamente para o jogo da noite.', NOW() + INTERVAL -54 DAY, NOW() + INTERVAL -55 DAY),
    (7, 10, NULL, 'Patrícia Rocha', 5, '["Localização","Atendimento"]', 'Jogar beach tennis com o pôr do sol do Guaíba não tem preço. Equipe super atenciosa.', 9, NULL, NULL, NOW() + INTERVAL -2 DAY),
    (8, 10, NULL, 'Diego Santos', 4, '["Custo-benefício"]', 'Areia boa e aluguel de raquete barato. Só faltou sombra entre os jogos.', 2, NULL, NULL, NOW() + INTERVAL -20 DAY),
    (9, 9, NULL, 'Thiago Oliveira', 5, '["Estrutura","Limpeza"]', 'Piso excelente e tabelas oficiais. Dá pra treinar de verdade.', 7, NULL, NULL, NOW() + INTERVAL -6 DAY),
    (10, 8, NULL, 'Juliana Pereira', 5, '["Atendimento"]', 'Lugar descontraído, areia limpa e o pessoal é muito gente boa.', 4, NULL, NULL, NOW() + INTERVAL -11 DAY),
    (11, 7, NULL, 'Gustavo Ribeiro', 4, '["Estrutura"]', 'Quadra coberta, ótima para dias de chuva. Arquibancada ajuda quando tem torcida.', 3, NULL, NULL, NOW() + INTERVAL -14 DAY),
    (12, 11, NULL, 'Aline Barbosa', 4, '["Custo-benefício","Estrutura"]', 'Grama nova e churrasqueira caprichada para depois do jogo.', 2, NULL, NULL, NOW() + INTERVAL -30 DAY),
    (13, 3, NULL, 'Eduardo Nunes', 5, '["Estrutura","Iluminação"]', 'Jogamos a pelada de quinta e foi show. Grama sintética macia, bola não quica estranho e a luz não ofusca.', 4, NULL, NULL, NOW() + INTERVAL -1 DAY),
    (14, 3, NULL, 'Larissa Mendes', 5, '["Atendimento"]', 'Reservei pelo site em dois minutos e chegando lá já estava tudo pronto. Coletes e bola emprestados sem custo.', 3, NULL, NULL, NOW() + INTERVAL -6 DAY),
    (15, 3, NULL, 'Henrique Prado', 5, '["Limpeza","Estrutura"]', 'Vestiário limpo, chuveiro quente e a lanchonete salva depois do jogo. Virou nosso campo fixo.', 2, NULL, NULL, NOW() + INTERVAL -12 DAY),
    (16, 3, NULL, 'Vinícius Rocha', 4, '["Custo-benefício"]', 'Preço justo pelo que oferece. Só acho que poderia ter um bebedouro dentro do campo.', 1, 'Boa ideia, Vinícius! Já estamos orçando um bebedouro na lateral do campo.', NOW() + INTERVAL -19 DAY, NOW() + INTERVAL -20 DAY),
    (17, 3, NULL, 'Priscila Andrade', 5, '["Localização","Atendimento"]', 'Fácil de chegar pelo centro de Viamão e o pessoal da recepção é muito atencioso. Recomendo para times femininos também!', 5, NULL, NULL, NOW() + INTERVAL -33 DAY),
    (18, 3, NULL, 'Marcos Vieira', 5, '["Iluminação"]', 'Jogo das 22h com iluminação perfeita. Dá para ver a bola em qualquer canto do campo.', 2, NULL, NULL, NOW() + INTERVAL -47 DAY),
    (19, 3, NULL, 'Tatiane Freitas', 4, '["Estrutura"]', 'Campo muito bom. A rede do gol estava com um furinho, mas avisamos e trocaram na semana seguinte.', 1, 'Obrigado por avisar, Tatiane! Rede trocada e conferida toda semana agora.', NOW() + INTERVAL -62 DAY, NOW() + INTERVAL -63 DAY),
    (20, 3, NULL, 'Rodrigo Teixeira', 5, '["Estrutura","Custo-benefício"]', 'Fizemos o aniversário do meu filho aqui. Campo, lanchonete e espaço para a família: tudo nota 10.', 3, 'Que alegria fazer parte desse aniversário, Rodrigo! Parabéns ao craque.', NOW() + INTERVAL -79 DAY, NOW() + INTERVAL -80 DAY),
    (21, 3, NULL, 'Natália Duarte', 5, '["Limpeza"]', 'Tudo muito organizado e limpo. Dá gosto de jogar num lugar cuidado assim.', 2, 'Obrigado, Natália! Cuidar bem do espaço é o nosso compromisso.', NOW() + INTERVAL -103 DAY, NOW() + INTERVAL -104 DAY),
    (22, 7, NULL, 'Felipe Moraes', 5, '["Estrutura"]', 'Piso de madeira em ótimo estado e as traves bem fixas. Futsal de verdade.', 6, NULL, NULL, NOW() + INTERVAL -2 DAY),
    (23, 7, NULL, 'Bianca Carvalho', 5, '["Atendimento","Limpeza"]', 'Quadra limpa e o seu Jorge da recepção é um querido. Sempre deixa a gente aquecer uns minutinhos antes.', 3, NULL, NULL, NOW() + INTERVAL -5 DAY),
    (24, 7, NULL, 'Leandro Pires', 4, '["Custo-benefício"]', 'Bom preço para uma quadra coberta. O vestiário é pequeno para dois times, mas dá conta.', 2, NULL, NULL, NOW() + INTERVAL -9 DAY),
    (25, 7, NULL, 'Carolina Batista', 5, '["Estrutura","Iluminação"]', 'Choveu a semana toda e a quadra coberta salvou o nosso campeonato da firma.', 4, NULL, NULL, NOW() + INTERVAL -18 DAY),
    (26, 7, NULL, 'Paulo Henrique', 4, '["Localização"]', 'Bem localizada na Avenida Central. Estacionamento enche rápido em horário de pico.', 1, NULL, NULL, NOW() + INTERVAL -23 DAY),
    (27, 7, NULL, 'Jéssica Lopes', 5, '["Atendimento"]', 'Reservamos para a escolinha das crianças e fomos super bem recebidos.', 2, NULL, NULL, NOW() + INTERVAL -31 DAY),
    (28, 7, NULL, 'Anderson Cruz', 3, '[]', 'A quadra é boa, mas o ar estava abafado no verão. Uns ventiladores a mais fariam diferença.', 3, NULL, NULL, NOW() + INTERVAL -38 DAY),
    (29, 7, NULL, 'Sabrina Melo', 5, '["Iluminação","Limpeza"]', 'Iluminação nova de LED e quadra impecável. Melhor futsal de Viamão.', 2, NULL, NULL, NOW() + INTERVAL -45 DAY),
    (30, 7, NULL, 'Ricardo Gomes', 4, '["Estrutura"]', 'Arquibancada boa para a torcida. Faltou um placar eletrônico, mas não atrapalhou.', 1, NULL, NULL, NOW() + INTERVAL -58 DAY),
    (31, 7, NULL, 'Daniela Fonseca', 5, '["Custo-benefício","Atendimento"]', 'Custo-benefício excelente e sempre tem horário à noite.', 3, NULL, NULL, NOW() + INTERVAL -70 DAY),
    (32, 7, NULL, 'Mateus Araújo', 5, '["Estrutura"]', 'Jogo toda segunda há meses e a quadra sempre está bem cuidada.', 2, NULL, NULL, NOW() + INTERVAL -86 DAY),
    (33, 7, NULL, 'Renata Silveira', 4, '["Limpeza"]', 'Ambiente limpo e organizado. O bebedouro estava sem água gelada no dia.', 1, NULL, NULL, NOW() + INTERVAL -99 DAY),
    (34, 7, NULL, 'Igor Machado', 5, '["Localização"]', 'Perto de casa, fácil de reservar e nunca tive problema com horário.', 2, NULL, NULL, NOW() + INTERVAL -121 DAY),
    (35, 7, NULL, 'Elaine Castro', 5, '["Atendimento"]', 'Organizamos um torneio de futsal feminino e a equipe ajudou em tudo.', 1, NULL, NULL, NOW() + INTERVAL -150 DAY),
    (36, 8, NULL, 'Amanda Ribeiro', 5, '["Estrutura","Limpeza"]', 'Areia fofinha e sem pedrinha nenhuma. A rede tem altura certinha para o vôlei.', 5, NULL, NULL, NOW() + INTERVAL -3 DAY),
    (37, 8, NULL, 'Caio Barros', 5, '["Atendimento"]', 'Galera da Play é muito parceira. Emprestaram bola e ainda deram dicas para a dupla iniciante.', 3, NULL, NULL, NOW() + INTERVAL -7 DAY),
    (38, 8, NULL, 'Letícia Campos', 5, '["Localização"]', 'No coração do Menino Deus, dá para ir de bicicleta. Ótimo para jogar depois do trabalho.', 2, NULL, NULL, NOW() + INTERVAL -13 DAY),
    (39, 8, NULL, 'Gabriel Antunes', 4, '["Custo-benefício"]', 'Bom preço por hora. Em dia de sol forte faltam guarda-sóis na área de descanso.', 2, NULL, NULL, NOW() + INTERVAL -19 DAY),
    (40, 8, NULL, 'Mariane Azevedo', 5, '["Iluminação"]', 'Jogamos à noite e a iluminação da quadra de areia é ótima. Não esperava!', 4, NULL, NULL, NOW() + INTERVAL -25 DAY),
    (41, 8, NULL, 'Otávio Brandão', 5, '["Estrutura"]', 'Duas quadras lado a lado, então dá para fazer mini torneio com os amigos.', 1, NULL, NULL, NOW() + INTERVAL -34 DAY),
    (42, 8, NULL, 'Débora Farias', 4, '["Limpeza"]', 'Vestiário simples, mas limpo. A areia é o ponto forte.', 1, NULL, NULL, NOW() + INTERVAL -42 DAY),
    (43, 8, NULL, 'Rafaela Moura', 5, '["Atendimento","Estrutura"]', 'Fiz uma aula experimental e já fechei o mês. Ambiente leve e acolhedor.', 3, NULL, NULL, NOW() + INTERVAL -51 DAY),
    (44, 8, NULL, 'Fábio Cardoso', 5, '["Custo-benefício"]', 'Melhor custo-benefício de vôlei de areia em Porto Alegre.', 2, NULL, NULL, NOW() + INTERVAL -64 DAY),
    (45, 8, NULL, 'Vanessa Teles', 4, '["Localização"]', 'Gostei bastante. Só é difícil achar vaga para estacionar na rua no fim de semana.', 1, NULL, NULL, NOW() + INTERVAL -77 DAY),
    (46, 8, NULL, 'Alexandre Lima', 5, '["Estrutura"]', 'Areia renovada recentemente, dá para mergulhar na bola sem medo.', 2, NULL, NULL, NOW() + INTERVAL -90 DAY),
    (47, 8, NULL, 'Cíntia Ramos', 4, '["Atendimento"]', 'Atendimento bom, mas a confirmação da reserva por WhatsApp demorou um pouco.', 1, NULL, NULL, NOW() + INTERVAL -112 DAY),
    (48, 8, NULL, 'Bernardo Klein', 5, '["Limpeza","Iluminação"]', 'Quadra bem cuidada e com luz boa até tarde. Voltaremos com certeza.', 2, NULL, NULL, NOW() + INTERVAL -135 DAY),
    (49, 8, NULL, 'Simone Pacheco', 4, '["Custo-benefício"]', 'Experiência boa no geral. Poderia ter aluguel de joelheira para quem está começando.', 1, NULL, NULL, NOW() + INTERVAL -160 DAY),
    (50, 9, NULL, 'Lucas Bittencourt', 5, '["Estrutura"]', 'Aro na altura oficial, tabela de vidro e piso que não escorrega. Coisa de primeiro mundo.', 6, NULL, NULL, NOW() + INTERVAL -1 DAY),
    (51, 9, NULL, 'Isabela Monteiro', 5, '["Iluminação","Limpeza"]', 'Iluminação de LED excelente e quadra sempre limpa. Nosso time treina aqui duas vezes por semana.', 4, NULL, NULL, NOW() + INTERVAL -4 DAY),
    (52, 9, NULL, 'Pedro Henrique Sá', 5, '["Atendimento"]', 'Equipe super prestativa, até ajudaram a montar o placar para o nosso amistoso.', 3, NULL, NULL, NOW() + INTERVAL -10 DAY),
    (53, 9, NULL, 'Mônica Rezende', 4, '["Localização"]', 'Quadra excelente. Fica numa avenida movimentada, então chegue com antecedência.', 2, NULL, NULL, NOW() + INTERVAL -15 DAY),
    (54, 9, NULL, 'Rogério Tavares', 5, '["Estrutura","Custo-benefício"]', 'Pelo preço, não tem quadra de basquete coberta melhor na cidade.', 3, NULL, NULL, NOW() + INTERVAL -21 DAY),
    (55, 9, NULL, 'Kelly Nascimento', 5, '["Limpeza"]', 'Vestiário limpo e bebedouro com água gelada. Detalhes que fazem diferença.', 2, NULL, NULL, NOW() + INTERVAL -29 DAY),
    (56, 9, NULL, 'André Fontoura', 5, '["Estrutura"]', 'Joguei 3x3 com os amigos e o piso emborrachado poupa muito o joelho.', 2, NULL, NULL, NOW() + INTERVAL -36 DAY),
    (57, 9, NULL, 'Luana Peixoto', 4, '["Custo-benefício"]', 'Ótima quadra. Seria legal ter um pacote mensal com desconto.', 1, NULL, NULL, NOW() + INTERVAL -44 DAY),
    (58, 9, NULL, 'Murilo Esteves', 5, '["Iluminação","Atendimento"]', 'Perfeita para jogo à noite. Atendimento rápido e simpático.', 3, NULL, NULL, NOW() + INTERVAL -55 DAY),
    (59, 9, NULL, 'Paula Guimarães', 5, '["Estrutura"]', 'Levei meu time sub-15 e a molecada amou a arquibancada para os pais.', 2, NULL, NULL, NOW() + INTERVAL -68 DAY),
    (60, 9, NULL, 'Sérgio Medeiros', 5, '["Limpeza","Estrutura"]', 'Quadra impecável, dá vontade de jogar todo dia.', 1, NULL, NULL, NOW() + INTERVAL -82 DAY),
    (61, 9, NULL, 'Talita Rios', 4, '["Localização"]', 'Boa quadra, mas não tem estacionamento próprio.', 1, NULL, NULL, NOW() + INTERVAL -97 DAY),
    (62, 9, NULL, 'Wagner Coelho', 5, '["Atendimento"]', 'Reserva fácil e sempre cumprem o horário certinho.', 2, NULL, NULL, NOW() + INTERVAL -118 DAY),
    (63, 9, NULL, 'Yasmin Correia', 5, '["Iluminação"]', 'Iluminação uniforme, sem sombra no garrafão. Dá para treinar arremesso tranquilo.', 1, NULL, NULL, NOW() + INTERVAL -140 DAY),
    (64, 10, NULL, 'Clara Fagundes', 5, '["Localização"]', 'Beira do Guaíba, fim de tarde, beach tennis com as amigas. Programa perfeito.', 5, NULL, NULL, NOW() + INTERVAL -4 DAY),
    (65, 10, NULL, 'Roberto Assis', 5, '["Atendimento","Custo-benefício"]', 'Alugaram raquete e bolinhas por um preço camarada. Ótimo para quem está começando.', 3, NULL, NULL, NOW() + INTERVAL -8 DAY),
    (66, 10, NULL, 'Fernanda Cunha', 5, '["Estrutura"]', 'Quatro quadras de areia bem niveladas e redes novas. O bar ao lado é um charme.', 4, NULL, NULL, NOW() + INTERVAL -12 DAY),
    (67, 10, NULL, 'Gustavo Lemos', 4, '["Localização"]', 'Lugar lindo, mas venta bastante no fim da tarde. Faz parte da orla!', 2, NULL, NULL, NOW() + INTERVAL -17 DAY),
    (68, 10, NULL, 'Helena Brum', 5, '["Iluminação"]', 'Jogamos até as 22h com iluminação ótima. Vista do Guaíba à noite também é linda.', 3, NULL, NULL, NOW() + INTERVAL -24 DAY),
    (69, 10, NULL, 'Júlio César Prates', 5, '["Atendimento"]', 'Professores muito bons. Fiz uma aula e já melhorei meu saque.', 2, NULL, NULL, NOW() + INTERVAL -30 DAY),
    (70, 10, NULL, 'Aline Siqueira', 5, '["Limpeza","Estrutura"]', 'Areia limpa, peneirada e funda na medida certa.', 2, NULL, NULL, NOW() + INTERVAL -39 DAY),
    (71, 10, NULL, 'Maurício Dorneles', 4, '["Custo-benefício"]', 'Preço bom, mas no fim de semana é difícil achar horário. Reserve com antecedência.', 1, NULL, NULL, NOW() + INTERVAL -48 DAY),
    (72, 10, NULL, 'Bruna Soares', 5, '["Localização","Estrutura"]', 'Melhor beach tennis de Porto Alegre, sem dúvida. Estacionamento amplo.', 3, NULL, NULL, NOW() + INTERVAL -60 DAY),
    (73, 10, NULL, 'Cristian Machado', 5, '["Atendimento"]', 'Atendimento nota 10 e o drink do bar depois do jogo fecha a noite.', 1, NULL, NULL, NOW() + INTERVAL -75 DAY),
    (74, 10, NULL, 'Marina Pacheco', 5, '["Iluminação","Limpeza"]', 'Ambiente bem cuidado, banheiros limpos e luz excelente.', 2, NULL, NULL, NOW() + INTERVAL -91 DAY),
    (75, 10, NULL, 'Eduarda Viana', 4, '["Estrutura"]', 'Quadras ótimas. Senti falta de um lugar coberto para esperar entre os jogos.', 1, NULL, NULL, NOW() + INTERVAL -108 DAY),
    (76, 10, NULL, 'Leonardo Furtado', 5, '["Custo-benefício","Localização"]', 'Vale cada centavo. Já virou o ponto de encontro da turma no verão.', 2, NULL, NULL, NOW() + INTERVAL -130 DAY),
    (77, 11, NULL, 'Diego Marques', 5, '["Estrutura"]', 'Grama sintética nova, dá gosto de jogar. A churrasqueira depois do jogo é tradição.', 4, NULL, NULL, NOW() + INTERVAL -2 DAY),
    (78, 11, NULL, 'Patrícia Moraes', 4, '["Custo-benefício"]', 'Um pouco mais caro que outros campos, mas a estrutura compensa.', 2, NULL, NULL, NOW() + INTERVAL -7 DAY),
    (79, 11, NULL, 'Thiago Becker', 5, '["Atendimento"]', 'Organizaram tudo para o churrasco da firma: campo, carvão e mesas. Nota 10.', 3, NULL, NULL, NOW() + INTERVAL -11 DAY),
    (80, 11, NULL, 'Sandra Luz', 3, '[]', 'O campo é bom, mas o vestiário precisa de reforma. Chuveiro com pouca pressão.', 2, NULL, NULL, NOW() + INTERVAL -16 DAY),
    (81, 11, NULL, 'Fabrício Ventura', 5, '["Iluminação"]', 'Os dois campos têm iluminação muito boa. Jogamos até meia-noite sem problema.', 2, NULL, NULL, NOW() + INTERVAL -22 DAY),
    (82, 11, NULL, 'Lívia Schmitt', 4, '["Localização"]', 'Fica um pouco longe do centro, mas tem bastante vaga para estacionar.', 1, NULL, NULL, NOW() + INTERVAL -28 DAY),
    (83, 11, NULL, 'Márcio Bueno', 5, '["Estrutura","Custo-benefício"]', 'Campo e espaço de confraternização no mesmo lugar. Para aniversário é perfeito.', 3, NULL, NULL, NOW() + INTERVAL -37 DAY),
    (84, 11, NULL, 'Raquel Damasceno', 4, '["Limpeza"]', 'Campo limpo e bem marcado. O banheiro feminino poderia ser maior.', 1, NULL, NULL, NOW() + INTERVAL -49 DAY),
    (85, 11, NULL, 'Jonas Wagner', 5, '["Atendimento"]', 'Sempre resolvem rápido quando precisamos trocar o horário.', 2, NULL, NULL, NOW() + INTERVAL -61 DAY),
    (86, 11, NULL, 'Viviane Brito', 3, '[]', 'O jogo anterior atrasou e perdemos 15 minutos. Pelo menos descontaram no valor.', 2, NULL, NULL, NOW() + INTERVAL -74 DAY),
    (87, 11, NULL, 'Nicolas Ferraz', 5, '["Estrutura"]', 'Grama excelente, bola rola rápido. Melhor society da Zona Norte.', 2, NULL, NULL, NOW() + INTERVAL -88 DAY),
    (88, 11, NULL, 'Rosana Kuhn', 4, '["Custo-benefício"]', 'Bom lugar. Se tivesse pacote para time fixo seria perfeito.', 1, NULL, NULL, NOW() + INTERVAL -103 DAY),
    (89, 11, NULL, 'Everton Lima', 5, '["Iluminação","Estrutura"]', 'Campo grande, iluminado e com rede de proteção alta. Não perde bola para a rua.', 1, NULL, NULL, NOW() + INTERVAL -125 DAY),
    (90, 11, NULL, 'Silvia Rangel', 5, '["Atendimento"]', 'Atendimento muito educado e campo sempre pronto no horário.', 1, NULL, NULL, NOW() + INTERVAL -148 DAY),
    (118, 12, NULL, 'Marcela Dutra', 5, '["Estrutura"]', 'Saibro bem cuidado e linhas sempre limpas. Dá gosto de jogar uma partida longa aqui.', 5, NULL, NULL, NOW() + INTERVAL -3 DAY),
    (119, 12, NULL, 'Roberto Kaminski', 5, '["Atendimento"]', 'Fiz uma aula avulsa com o professor Marcos e corrigi meu backhand em uma hora.', 3, NULL, NULL, NOW() + INTERVAL -7 DAY),
    (120, 12, NULL, 'Ana Paula Wolf', 5, '["Localização","Estrutura"]', 'Ambiente tranquilo e cheio de verde, parece que você nem está em Porto Alegre.', 2, NULL, NULL, NOW() + INTERVAL -13 DAY),
    (121, 12, NULL, 'Felipe Rossi', 4, '["Custo-benefício"]', 'Quadras excelentes. O preço é um pouco acima da média, mas a estrutura justifica.', 2, NULL, NULL, NOW() + INTERVAL -19 DAY),
    (122, 12, NULL, 'Carolina Benites', 5, '["Iluminação"]', 'Jogamos à noite na quadra de piso rápido e a iluminação é perfeita, sem sombra.', 3, NULL, NULL, NOW() + INTERVAL -26 DAY),
    (123, 12, NULL, 'Marcelo Dorneles', 5, '["Estrutura"]', 'A máquina de bolinhas é ótima para treinar sozinho.', 2, NULL, NULL, NOW() + INTERVAL -34 DAY),
    (124, 12, NULL, 'Bianca Thomé', 5, '["Limpeza","Atendimento"]', 'Vestiário impecável e o café do clube é uma delícia depois do jogo.', 2, NULL, NULL, NOW() + INTERVAL -43 DAY),
    (125, 12, NULL, 'Alexandre Pires', 4, '["Localização"]', 'Quadras ótimas, mas o estacionamento é pequeno para o movimento do sábado.', 1, NULL, NULL, NOW() + INTERVAL -55 DAY),
    (126, 12, NULL, 'Letícia Fagundes', 5, '["Atendimento"]', 'Alugaram raquete para minha filha de 10 anos e ainda deram dicas para ela. Muito atenciosos.', 2, NULL, NULL, NOW() + INTERVAL -68 DAY),
    (127, 12, NULL, 'Vitor Hugo Lima', 5, '["Estrutura"]', 'O melhor saibro em que já joguei na cidade.', 1, NULL, NULL, NOW() + INTERVAL -84 DAY),
    (128, 12, NULL, 'Sofia Rangel', 5, '["Custo-benefício"]', 'O pacote de 4 horas no mês sai bem em conta.', 1, NULL, NULL, NOW() + INTERVAL -102 DAY),
    (129, 12, NULL, 'Gilberto Nunes', 5, '["Estrutura","Limpeza"]', 'Quadras sempre regadas e niveladas antes do horário. Profissionalismo total.', 1, NULL, NULL, NOW() + INTERVAL -130 DAY),
    (130, 13, NULL, 'Yuri Tanaka', 5, '["Estrutura","Iluminação"]', 'Quadras oficiais com iluminação sem reflexo. Finalmente um lugar sério para badminton na região.', 4, NULL, NULL, NOW() + INTERVAL -2 DAY),
    (131, 13, NULL, 'Clarissa Mota', 5, '["Atendimento"]', 'Nunca tinha jogado e me emprestaram raquete e peteca. Já quero voltar!', 3, NULL, NULL, NOW() + INTERVAL -6 DAY),
    (132, 13, NULL, 'Danilo Ferreira', 4, '["Custo-benefício"]', 'Preço ótimo por hora. As petecas emprestadas estavam um pouco gastas.', 2, NULL, NULL, NOW() + INTERVAL -11 DAY),
    (133, 13, NULL, 'Helena Kato', 5, '["Estrutura"]', 'Ar-condicionado faz toda a diferença, a peteca não sofre com vento.', 2, NULL, NULL, NOW() + INTERVAL -16 DAY),
    (134, 13, NULL, 'Marcos Paulo Silva', 4, '["Localização"]', 'Bem localizado na Flores da Cunha, mas a vaga na rua é disputada.', 1, NULL, NULL, NOW() + INTERVAL -24 DAY),
    (135, 13, NULL, 'Priscila Amaral', 5, '["Limpeza"]', 'Piso limpo e sem poeira, dá para fazer movimentos rápidos sem escorregar.', 2, NULL, NULL, NOW() + INTERVAL -31 DAY),
    (136, 13, NULL, 'Jonathan Becker', 4, '["Estrutura"]', 'Ótimo ginásio. Poderia ter mais horários de manhã.', 1, NULL, NULL, NOW() + INTERVAL -42 DAY),
    (137, 13, NULL, 'Lara Medeiros', 5, '["Atendimento","Custo-benefício"]', 'Grupo de iniciantes às quartas é muito acolhedor. Recomendo para quem quer começar.', 2, NULL, NULL, NOW() + INTERVAL -53 DAY),
    (138, 13, NULL, 'Ricardo Ito', 4, '["Limpeza"]', 'Vestiário simples, mas limpo. As quadras são o ponto forte.', 1, NULL, NULL, NOW() + INTERVAL -67 DAY),
    (139, 13, NULL, 'Natasha Vieira', 5, '["Estrutura"]', 'Redes na altura oficial e linhas bem marcadas. Ótimo para treinar para torneios.', 1, NULL, NULL, NOW() + INTERVAL -85 DAY),
    (140, 13, NULL, 'Caetano Brito', 4, '["Custo-benefício"]', 'Bom custo-benefício. Seria legal vender petecas de pena na recepção.', 1, NULL, NULL, NOW() + INTERVAL -104 DAY),
    (141, 13, NULL, 'Mirela Santos', 5, '["Atendimento"]', 'O dono é apaixonado pelo esporte e isso aparece em cada detalhe.', 1, NULL, NULL, NOW() + INTERVAL -128 DAY),
    (142, 14, NULL, 'Jean Carlos Souza', 5, '["Estrutura"]', 'Pelada boa e depois todo mundo no bar vendo o Gre-Nal no telão. Programa completo.', 5, NULL, NULL, NOW() + INTERVAL -1 DAY),
    (143, 14, NULL, 'Márcia Kroeff', 4, '["Localização"]', 'No centro de Canoas, fácil de chegar de trem. O estacionamento lota em dia de jogo.', 2, NULL, NULL, NOW() + INTERVAL -5 DAY),
    (144, 14, NULL, 'Wellington Dias', 4, '["Custo-benefício"]', 'Preço justo. A grama já está um pouco gasta perto das goleiras.', 2, NULL, NULL, NOW() + INTERVAL -9 DAY),
    (145, 14, NULL, 'Luana Teixeira', 5, '["Iluminação"]', 'Refletores de LED novos, a noite parece dia.', 3, NULL, NULL, NOW() + INTERVAL -14 DAY),
    (146, 14, NULL, 'Fábio Jung', 3, '[]', 'O jogo anterior passou do horário e começamos 10 minutos atrasados. O campo em si é bom.', 3, NULL, NULL, NOW() + INTERVAL -20 DAY),
    (147, 14, NULL, 'Caroline Melo', 4, '["Atendimento"]', 'Atendimento simpático. Poderiam ter bola para emprestar.', 1, NULL, NULL, NOW() + INTERVAL -26 DAY),
    (148, 14, NULL, 'Rogério Klein', 5, '["Estrutura","Custo-benefício"]', 'Bom campo, bom preço e cerveja gelada no bar. O que mais precisa?', 2, NULL, NULL, NOW() + INTERVAL -33 DAY),
    (149, 14, NULL, 'Simone Gaspar', 4, '["Limpeza"]', 'Vestiário limpo, mas só tem dois chuveiros para dois times.', 1, NULL, NULL, NOW() + INTERVAL -41 DAY),
    (150, 14, NULL, 'Anderson Lopes', 5, '["Localização"]', 'Ao lado do parque, dá para levar as crianças que ficam brincando enquanto a gente joga.', 2, NULL, NULL, NOW() + INTERVAL -50 DAY),
    (151, 14, NULL, 'Patrícia Hoff', 4, '["Estrutura"]', 'Campo bom. Faltou rede atrás das goleiras, a bola vai longe.', 1, NULL, NULL, NOW() + INTERVAL -62 DAY),
    (152, 14, NULL, 'Cláudio Rosa', 3, '[]', 'Em dia de chuva o campo acumula água num dos cantos. Precisa melhorar a drenagem.', 2, NULL, NULL, NOW() + INTERVAL -75 DAY),
    (153, 14, NULL, 'Daiane Moraes', 5, '["Atendimento"]', 'Fizemos o jogo solidário da escola aqui e a direção do campo ajudou em tudo.', 1, NULL, NULL, NOW() + INTERVAL -89 DAY),
    (154, 14, NULL, 'Everton Costa', 4, '["Custo-benefício"]', 'Boa opção para quem mora em Canoas. Nada de excepcional, mas cumpre bem.', 1, NULL, NULL, NOW() + INTERVAL -108 DAY),
    (155, 14, NULL, 'Kátia Fraga', 5, '["Iluminação","Estrutura"]', 'Iluminação excelente e grama boa. Nosso time fixo de terça joga aqui há um ano.', 1, NULL, NULL, NOW() + INTERVAL -132 DAY),
    (156, 15, NULL, 'Kauã Pereira', 5, '["Estrutura"]', 'Quadra 3x3 com som ambiente e cobertura. A vibe é de basquete de rua, mas com estrutura boa.', 5, NULL, NULL, NOW() + INTERVAL -2 DAY),
    (157, 15, NULL, 'Bruna Klafke', 5, '["Custo-benefício"]', 'Preço camarada por hora, dá para dividir entre seis e sai quase de graça.', 3, NULL, NULL, NOW() + INTERVAL -6 DAY),
    (158, 15, NULL, 'Leandro Saraiva', 4, '["Localização"]', 'Bom lugar. Fica num bairro residencial, então o som tem que baixar às 22h.', 2, NULL, NULL, NOW() + INTERVAL -10 DAY),
    (159, 15, NULL, 'Thalia Gonçalves', 5, '["Estrutura","Limpeza"]', 'Piso de alta aderência e sempre limpo. Nunca escorreguei.', 2, NULL, NULL, NOW() + INTERVAL -15 DAY),
    (160, 15, NULL, 'Wesley Nascimento', 5, '["Atendimento"]', 'Organizaram um campeonato 3x3 no sábado. A galera de Gravataí compareceu em peso!', 2, NULL, NULL, NOW() + INTERVAL -22 DAY),
    (161, 15, NULL, 'Marina Freitas', 4, '["Estrutura"]', 'A quadra é ótima, mas não tem vestiário, só banheiro.', 1, NULL, NULL, NOW() + INTERVAL -30 DAY),
    (162, 15, NULL, 'Igor Bittencourt', 5, '["Iluminação"]', 'Luz boa até tarde da noite e a cobertura salva nos dias de chuva.', 2, NULL, NULL, NOW() + INTERVAL -39 DAY),
    (163, 15, NULL, 'Rayssa Lima', 4, '["Custo-benefício"]', 'Gostei. Seria legal ter bola para alugar.', 1, NULL, NULL, NOW() + INTERVAL -48 DAY),
    (164, 15, NULL, 'Daniel Assis', 5, '["Estrutura"]', 'Tabela de acrílico e aro com mola. Dá para enterrar sem medo.', 2, NULL, NULL, NOW() + INTERVAL -60 DAY),
    (165, 15, NULL, 'Paola Rocha', 5, '["Localização"]', 'Tem bicicletário, então vou pedalando de casa. Ótimo!', 1, NULL, NULL, NOW() + INTERVAL -76 DAY),
    (166, 15, NULL, 'Vinícius Prestes', 4, '["Limpeza"]', 'Quadra boa, o bebedouro às vezes fica sem água gelada.', 1, NULL, NULL, NOW() + INTERVAL -95 DAY),
    (167, 15, NULL, 'Larissa Antunes', 5, '["Atendimento"]', 'Ambiente respeitoso, as meninas do time se sentem bem-vindas.', 1, NULL, NULL, NOW() + INTERVAL -117 DAY),
    (168, 15, NULL, 'Otávio Mendes', 4, '["Estrutura"]', 'Boa quadra para 3x3. Para 5x5 fica apertado, mas não é a proposta.', 1, NULL, NULL, NOW() + INTERVAL -142 DAY),
    (169, 16, NULL, 'Gabriel Wingert', 5, '["Estrutura"]', 'Quadra coberta de piso rápido em ótimo estado. Choveu o dia todo e jogamos tranquilos.', 4, NULL, NULL, NOW() + INTERVAL -2 DAY),
    (170, 16, NULL, 'Juliana Spohr', 5, '["Atendimento"]', 'Fiz aula para iniciantes e o professor foi muito paciente. Saí jogando!', 3, NULL, NULL, NOW() + INTERVAL -6 DAY),
    (171, 16, NULL, 'Ricardo Schaefer', 4, '["Custo-benefício"]', 'Preço bom para quadra coberta. O vestiário é pequeno.', 2, NULL, NULL, NOW() + INTERVAL -11 DAY),
    (172, 16, NULL, 'Bruna Hoffmann', 5, '["Iluminação"]', 'Iluminação perfeita para jogar à noite, sem reflexo no piso.', 2, NULL, NULL, NOW() + INTERVAL -17 DAY),
    (173, 16, NULL, 'Marcos Ritter', 5, '["Estrutura","Limpeza"]', 'Quadras limpas, redes novas e a máquina de bolinhas funciona muito bem.', 2, NULL, NULL, NOW() + INTERVAL -24 DAY),
    (174, 16, NULL, 'Camila Bauer', 4, '["Localização"]', 'Fica no centro histórico de Hamburgo Velho, lindo. Estacionar na rua é que é difícil.', 1, NULL, NULL, NOW() + INTERVAL -33 DAY),
    (175, 16, NULL, 'Pedro Klein', 5, '["Atendimento"]', 'Reservei para jogar com meu pai e fomos muito bem atendidos.', 2, NULL, NULL, NOW() + INTERVAL -45 DAY),
    (176, 16, NULL, 'Larissa Zimmer', 4, '["Estrutura"]', 'Piso rápido é ótimo, mas para quem prefere saibro não é a melhor opção.', 1, NULL, NULL, NOW() + INTERVAL -58 DAY),
    (177, 16, NULL, 'Fernando Kunz', 5, '["Custo-benefício"]', 'O pacote mensal vale muito a pena para quem joga toda semana.', 1, NULL, NULL, NOW() + INTERVAL -72 DAY),
    (178, 16, NULL, 'Aline Ruschel', 5, '["Limpeza","Atendimento"]', 'Ambiente agradável, limpo e o pessoal da recepção é muito simpático.', 1, NULL, NULL, NOW() + INTERVAL -90 DAY),
    (179, 16, NULL, 'Otávio Sperb', 4, '["Iluminação"]', 'Boa quadra. Uma das lâmpadas estava fraca, mas trocaram na semana seguinte.', 1, NULL, NULL, NOW() + INTERVAL -112 DAY),
    (180, 16, NULL, 'Helena Mossmann', 5, '["Estrutura"]', 'Melhor quadra coberta de tênis do Vale do Sinos.', 1, NULL, NULL, NOW() + INTERVAL -138 DAY),
    (181, 17, NULL, 'Beatriz Lacerda', 5, '["Estrutura"]', 'Piso de madeira impecável e rede na altura feminina oficial. Treino do nosso time ficou outro nível.', 5, NULL, NULL, NOW() + INTERVAL -1 DAY),
    (182, 17, NULL, 'Rafael Moreira', 4, '["Custo-benefício"]', 'Preço justo dividindo entre 12 pessoas. Sozinho fica caro, mas é o ginásio inteiro.', 2, NULL, NULL, NOW() + INTERVAL -5 DAY),
    (183, 17, NULL, 'Tatiana Prado', 5, '["Estrutura","Iluminação"]', 'Placar eletrônico e iluminação ótima. Parece jogo de campeonato.', 3, NULL, NULL, NOW() + INTERVAL -9 DAY),
    (184, 17, NULL, 'Lucas Bertolini', 5, '["Atendimento"]', 'Ajudaram a regular a rede para o jogo misto. Equipe muito prestativa.', 2, NULL, NULL, NOW() + INTERVAL -14 DAY),
    (185, 17, NULL, 'Mariana Fontes', 3, '[]', 'O ginásio é bom, mas estava muito quente. Faltam ventiladores no verão.', 3, NULL, NULL, NOW() + INTERVAL -20 DAY),
    (186, 17, NULL, 'Diego Amaral', 5, '["Localização"]', 'Na Protásio, fácil de chegar de ônibus. Nosso grupo de vôlei de quarta joga aqui.', 2, NULL, NULL, NOW() + INTERVAL -27 DAY),
    (187, 17, NULL, 'Carla Weiss', 4, '["Limpeza"]', 'Vestiários limpos. A arquibancada podia ter mais lugares.', 1, NULL, NULL, NOW() + INTERVAL -35 DAY),
    (188, 17, NULL, 'Henrique Salles', 5, '["Estrutura"]', 'Pé-direito alto, a bola não bate no teto em levantamento nenhum.', 2, NULL, NULL, NOW() + INTERVAL -44 DAY),
    (189, 17, NULL, 'Sabrina Guedes', 4, '["Custo-benefício"]', 'Bom lugar. Poderia ter horário de meia quadra mais barato.', 1, NULL, NULL, NOW() + INTERVAL -56 DAY),
