    (192, 17, NULL, 'Eduarda Nunes', 5, '["Estrutura"]', 'Finalmente um ginásio de vôlei de verdade para alugar em Porto Alegre.', 1, NULL, NULL, NOW() + INTERVAL -121 DAY);
